// crates/domain/session/src/aggregates/session.rs の末尾
#[cfg(test)]
mod tests {
    use super::*;

    /// traces: I45
    #[test]
    fn closed_session_is_not_reopened() {
        let closed = closed_session("P1");
        assert_eq!(closed.reopen(), Err(SessionError::Closed));
    }

    // Creation Method：このテストに効かない欄は既定の値で埋める
    fn closed_session(id: &str) -> Session { Session::open(sid(id), purpose("ACDR 0197")).close() }
}

